INSERT INTO feature VALUES('model-include','modules','Model includes','modules','implemented','notable',NULL,'A module body''s `include M ;` takes the module `M`''s members as its own when the module closes, its exports when `M` is ascribed, so a model of a theory including another builds on a model of the included one rather than restating it, and its reduct at the included theory is that model, member for member; a name the body also writes is refused as a second definition, and a name no module answers is refused by that name.','surface-grammar surface-lowering core-checker','corpus/model/modules/model-include.gandr corpus/pathological/modules/model-include.gandr','corpus/model/modules/model-include.gandr',NULL);
